def dehydrate_timedelta(value):
    """Dehydrate a timedelta into a JSON-serializable dict.

    Parameters
    ----------
    value : datetime.timedelta
        The timedelta instance to dehydrate.

    Returns
    -------
    dict | None
        Dictionary with days, seconds, microseconds or None on error.
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError('value must be a datetime.timedelta')
    try:
        return {
            'days': value.days,
            'seconds': value.seconds,
            'microseconds': value.microseconds,
        }
    except Exception:
        return None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    try:
        from datetime import time as _time
    except Exception as exc:
        raise RuntimeError("datetime module not available") from exc

    if value is None:
        return None

    if not isinstance(value, _time):
        raise TypeError(f"value must be a datetime.time instance, got {type(value)!r}")

    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None

    # Ensure the object has the expected attributes
    required_attrs = ('lat', 'lon', 'time')
    missing_attrs = [attr for attr in required_attrs if not hasattr(value, attr)]
    if missing_attrs:
        raise TypeError(
            f"Expected a Point instance with attributes {required_attrs}, "
            f"but missing {', '.join(missing_attrs)}"
        )

    try:
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time_val = getattr(value, 'time')
    except Exception as exc:
        raise ValueError(f"Error accessing Point attributes: {exc}") from exc

    # Convert the time to an ISO format string if possible
    if hasattr(time_val, 'isoformat'):
        time_str = time_val.isoformat()
    else:
        time_str = str(time_val)

    return {'lat': lat, 'lon': lon, 'time': time_str}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated _keys attribute if present
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            return list(self._keys.keys())
        # Fallback to a common 'data' attribute
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())
    except Exception:
        pass
    # As a last resort, return public attributes from __dict__
    if hasattr(self, "__dict__"):
        return [k for k in self.__dict__ if not k.startswith("_")]
    # If nothing available, return an empty list
    return []

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers.

    The dictionary is keyed by version tuple. If *protocol_version* is provided,
    the dictionary contains either zero or one items depending on whether
    that version is supported. If *protocol_version* is omitted or ``None``,
    the dictionary returns all available protocol versions.

    :param protocol_version: tuple identifying a specific protocol version
        (e.g. (3, 5)) or ``None``
    :return: dictionary of version tuple to handler class for all relevant
        and supported protocol versions
    :raise TypeError: if *protocol_version* is not a tuple or ``None``"""

    # Validate input
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError(
            f"protocol_version must be a tuple (or None), got {type(protocol_version).__name__}"
        )

    # Retrieve the registry of handlers; subclasses may override this attribute
    handlers = getattr(cls, "PROTOCOL_HANDLERS", {})
    if not isinstance(handlers, dict):
        # If the attribute is unexpected, treat as empty
        handlers = {}

    if protocol_version is None:
        # Return a copy to avoid accidental mutations
        return handlers.copy()

    # Return only the requested version if it exists
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Attempt to use an internal index container if it exists
    try:
        idx_container = self._index
    except AttributeError:
        # Fallback to treating the object itself as a sequence
        idx_container = list(self)

    # If the container is sorted, use binary search for efficiency
    if getattr(self, "_sort", False):
        try:
            import bisect
            i = bisect.bisect_left(idx_container, key)
            if i != len(idx_container) and idx_container[i] == key:
                return i
        except Exception:
            # Fall back to linear search if bisect fails
            pass

    # Linear search as a safe fallback
    try:
        return idx_container.index(key)
    except ValueError:
        pass

    # If key was not found, raise an appropriate error
    raise KeyError(f"'{key}' not found")

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # Underlying data may be stored in several attributes.
        data = getattr(self, "_items", None) or getattr(self, "_record", None)
        if data is None:
            raise AttributeError("The record has no data to retrieve values from.")

        # If data is a dictionary.
        if isinstance(data, dict):
            if not keys:
                return list(data.values())

            values_list = []
            for k in keys:
                if isinstance(k, int):
                    try:
                        values_list.append(list(data.values())[k])
                    except IndexError:
                        raise IndexError(f"Index {k} is out of range.")
                else:
                    if k not in data:
                        raise KeyError(f"Key '{k}' not found.")
                    values_list.append(data[k])
            return values_list

        # If data is a list or tuple.
        if isinstance(data, (list, tuple)):
            if not keys:
                return list(data)

            values_list = []
            for k in keys:
                if isinstance(k, int):
                    try:
                        values_list.append(data[k])
                    except IndexError:
                        raise IndexError(f"Index {k} is out of range.")
                else:
                    try:
                        idx = int(k)
                    except (ValueError, TypeError):
                        raise TypeError("Keys for a list must be integers, got %r" % k)
                    try:
                        values_list.append(data[idx])
                    except IndexError:
                        raise IndexError(f"Index {idx} is out of range.")
            return values_list

        # Generic iterable fallback.
        try:
            all_values = list(iter(data))
        except TypeError:
            raise TypeError("Record data is not iterable.")

        if not keys:
            return all_values

        values_list = []
        for k in keys:
            if isinstance(k, int):
                try:
                    values_list.append(all_values[k])
                except IndexError:
                    raise IndexError(f"Index {k} out of range.")
            else:
                # No meaningful non-integer key for a generic iterable.
                raise TypeError("Cannot filter a generic iterable by non-integer key.")
        return values_list

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of bounds will trigger an IndexError.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: IndexError if an out-of-bounds index is specified
    """
    # Attempt to locate the underlying data structures
    # The record is expected to store values in a list or tuple `self._data`
    # and the corresponding names in a list `self._keys`. If those attributes
    # are not present, fall back to using a dict-like mapping if available.
    try:
        values = self._data
        names = self._keys
    except AttributeError:
        # Try alternate attribute names that may be used by different
        # implementations. If none exist, attempt to use the object's __dict__.
        values = getattr(self, '_values', None)
        names = getattr(self, '_names', None)
        if values is None or names is None:
            # Use the instance's dictionary as a last resort
            # This will give all attributes of the object that are not
            # internal (starting with underscore).
            return {k: v for k, v in vars(self).items() if not k.startswith('_')}

    # Build a mapping of name->value based on the full record
    full_dict = {name: val for name, val in zip(names, values)}

    if not keys:
        return full_dict

    result = {}
    for key in keys:
        # Integer index handling
        if isinstance(key, int):
            if key < 0 or key >= len(values):
                raise IndexError(f"Index {key} out of bounds")
            name = names[key]
            result[name] = values[key]
        else:
            # Key name handling
            if key in full_dict:
                result[key] = full_dict[key]
            else:
                result[key] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer. """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit integer")
    # Grab last two bytes
    last_two = self.data[-2:]
    # Remove the bytes from the buffer
    if isinstance(self.data, (bytearray, list)):
        del self.data[-2:]
    else:
        # For immutable types (bytes, str), assign a new trimmed value
        self.data = self.data[:-2]
    # Convert to unsigned int, big-endian
    return int.from_bytes(last_two, byteorder='big')

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in {"READ", "WRITE"}:
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Prepare the payload
    payload = {}
    if mode: payload["mode"] = mode
    if bookmarks:
        # Ensure bookmarks is an iterable of strings (or values convertible to str)
        try:
            payload["bookmarks"] = list(bookmarks)
        except Exception as exc:
            raise ValueError("bookmarks must be an iterable") from exc
    if metadata:
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary")
        payload["metadata"] = metadata
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number")
        payload["timeout"] = timeout
    if db:
        payload["db"] = db
    if imp_user:
        payload["imp_user"] = imp_user
    if dehydration_hooks:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        payload["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        payload["hydration_hooks"] = hydration_hooks

    # Construct the BEGIN message
    begin_msg = {"type": "BEGIN", "payload": payload}

    # Attempt to append to an output queue or use a sending method
    try:
        if hasattr(self, "_output_queue") and isinstance(self._output_queue, list):
            self._output_queue.append(begin_msg)
        elif hasattr(self, "_send_message") and callable(getattr(self, "_send_message")):
            self._send_message(begin_msg)
        else:
            raise RuntimeError("No output queue or send method available")
    except Exception as exc:
        raise RuntimeError("Failed to enqueue BEGIN message") from exc

    # Create a lightweight Response object to hold handlers
    class Response:
        """Minimal Response placeholder for transaction handling."""
        def __init__(self, handlers):
            self.handlers = handlers

    return Response(handlers)

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""
    # Try to use Point as base; fall back to object if unavailable
    try:
        Base = Point
    except NameError:
        Base = object

    # Build the class namespace
    namespace = {}

    # Store the SRID in a class attribute if provided
    namespace['srid'] = srid_map.get(name, None)

    # Define __slots__ to keep instances lightweight
    namespace['__slots__'] = tuple(fields)

    # Construct a flexible __init__ that accepts positional arguments
    def __init__(self, *values):
        expected = len(fields)
        if len(values) != expected:
            raise TypeError(
                f"{name}() expected {expected} arguments, got {len(values)}"
            )
        for field_name, value in zip(fields, values):
            setattr(self, field_name, value)
        # Call super init if it exists
        if hasattr(Base, "__init__"):
            Base.__init__(self)

    namespace['__init__'] = __init__

    # Create and return the new subclass
    cls = type(name, (Base,), namespace)
    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return (0,)
    parts = s.split('.')
    nums = []
    for part in parts:
        # Extract leading numeric characters from each part.
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
    if not nums:
        return (0,)
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    # Retrieve the storage dictionary; this should be defined in the class.
    storage = getattr(self, 'storage', None)
    if storage is None:
        raise AttributeError("The instance does not contain a 'storage' attribute.")

    # If the key already exists, return its value.
    if key in storage:
        return storage[key]

    # Otherwise, set the key to the default value and return it.
    try:
        storage[key] = default
        # Mark the storage as changed if applicable (e.g., for persistent objects).
        if hasattr(storage, "_p_changed"):
            storage._p_changed = True
        return default
    except Exception as exc:
        raise RuntimeError(f"Failed to set default for key '{key}': {exc}") from exc

def get(self, key, default=None):
        """
        D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
        """
        # Try to fetch the value; handle any unexpected errors gracefully.
        try:
            if key in self:
                return self[key]
        except Exception:
            # An error may occur (e.g., unhashable key), so fall back to default.
            return default
        # Key is not present in the dictionary.
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
