def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    impl_cls_name = self.__class__.__name__
    # Strip known suffixes
    for suffix in ('Py', 'Fallback'):
        if impl_cls_name.endswith(suffix):
            impl_cls_name = impl_cls_name[:-len(suffix)]
            break
    module_name = getattr(self.__class__, "__module__", None)
    if not module_name:
        raise RuntimeError("Cannot determine module for class %s" % type(self))
    try:
        module = sys.modules[module_name]
    except KeyError:
        # Module not loaded: try importing it
        try:
            __import__(module_name)
            module = sys.modules[module_name]
        except ImportError as exc:
            raise RuntimeError("Module '%s' not importable" % module_name) from exc
    # Get the target class from the module
    try:
        target_cls = getattr(module, impl_cls_name)
    except AttributeError as exc:
        raise RuntimeError("Target class '%s' not found in module '%s'" % (impl_cls_name, module_name)) from exc
    if not isinstance(target_cls, type):
        raise RuntimeError("Attribute '%s' in module '%s' is not a class" % (impl_cls_name, module_name))
    return target_cls

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects") from None

    minimal = []
    seen = set()
    for cls in iterator:
        if not isinstance(cls, type):
            raise TypeError(f"expected a class object, got {type(cls).__name__}")
        if cls in seen:
            # skip duplicates
            continue
        # keep cls only if it is not a subclass of any already kept class
        if not any(issubclass(cls, base) for base in minimal):
            minimal.append(cls)
            seen.add(cls)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    names = {}
    try:
        mro = self.__class__.__mro__ if all else [self.__class__]
    except AttributeError:
        mro = [self.__class__]
    seen = set()
    for cls in mro:
        for name, member in cls.__dict__.items():
            # Skip internal attributes.
            if name.startswith("_"):
                continue
            # Avoid duplicates from base classes.
            if name in seen:
                continue
            seen.add(name)
            desc = None
            # Handle property objects.
            if isinstance(member, property):
                desc = member.__doc__
                if desc is None and hasattr(member.fget, "__doc__"):
                    desc = member.fget.__doc__
            # Handle methods or functions.
            elif callable(member):
                desc = member.__doc__
            # If the member has a __doc__ attribute directly.
            elif hasattr(member, "__doc__"):
                desc = member.__doc__
            # Only add if a description is available.
            if desc is not None:
                # Remove surrounding whitespace.
                desc = desc.strip() if isinstance(desc, str) else desc
                names[name] = desc
    return names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle None explicitly
    if sequence is None:
        return output

    # If the input is a collection (list, tuple, set), iterate and recurse
    if isinstance(sequence, (list, tuple, set)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        # Anything else is treated as a single interface/spec
        output.append(sequence)

    return output

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context to an empty dictionary
        if hasattr(self, 'context'):
            self.context = {}
        else:
            # If the attribute does not exist, create it
            self.context = {}

        # Reinitialize bins
        if hasattr(self, 'initial_value') and self.initial_value is not None:
            # If bins already exist, preserve their length
            if hasattr(self, 'bins'):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                self.bins = [self.initial_value]
        else:
            # Fall back to a method that creates bins dynamically
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                try:
                    self.bins = self.make_bins()
                except Exception as e:
                    # In case bin creation fails, store an empty list
                    self.bins = []
                    raise RuntimeError(f"Failed to create bins: {e}") from e
            else:
                # If no bin creation method is available, store an empty list
                self.bins = []

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    # Optional header
    if header is not None:
        if isinstance(header, (list, tuple)):
            header_line = separator.join(str(h) for h in header)
        else:
            header_line = str(header)
        lines.append(header_line)

    # Iterate over the graph points
    for point in self:
        try:
            # Attempt to extract coordinates and values
            if hasattr(point, "coordinate") and hasattr(point, "value"):
                coords = point.coordinate
                values = point.value
            elif isinstance(point, tuple):
                # Expect (coords, values) or a flat tuple
                if len(point) == 2:
                    coords, values = point
                else:
                    coords, values = point[0], tuple(point[1:])
            else:
                # Fallback: if point is iterable, split first part as coords
                try:
                    coords, values = point
                except Exception:
                    coords = point
                    values = ()
        except Exception:
            # Skip points that cannot be interpreted
            continue

        # Convert coordinates to string list
        if isinstance(coords, (list, tuple)):
            coord_parts = [str(c) for c in coords]
        else:
            coord_parts = [str(coords)]

        # Convert values to string list, treating non-string iterables as parts
        if isinstance(values, (list, tuple)):
            value_parts = [str(v) for v in values]
        else:
            # Strings are considered a single value, not split
            value_parts = [str(values)]

        # Form the CSV line
        line = separator.join(coord_parts + value_parts)
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError(
            f"coord_name must be a string, got {type(coord_name).__name__}"
        )
    # Primary source: a dedicated error-indices mapping if it exists
    try:
        err_map = getattr(self, "_err_indices", None)
        if isinstance(err_map, dict):
            return list(err_map.get(coord_name, []))
    except Exception:
        # ignore any issues accessing _err_indices
        pass

    # Fallback: look into coordinate variable metadata
    try:
        coords = getattr(self, "coords", {})
        if isinstance(coords, dict):
            coord_obj = coords.get(coord_name)
            if coord_obj is not None:
                # Common pattern: an attribute `error_indices`
                if hasattr(coord_obj, "error_indices"):
                    return list(coord_obj.error_indices)
                # Or a simple dict entry
                if isinstance(coord_obj, dict) and "error_indices" in coord_obj:
                    return list(coord_obj["error_indices"])
    except Exception:
        # ignore any issues in the fallback path
        pass

    # Default: no error indices found
    return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    bins_arr = np.asarray(bins)

    # Determine widths for each dimension
    if isinstance(edges, tuple):
        widths = [np.diff(e) for e in edges]
    else:
        # 1‑D case
        widths = [np.diff(edges)]

    # Validate shape consistency
    try:
        ndim = len(widths)
        exp_shape = tuple(len(w) for w in widths)
        if bins_arr.shape != exp_shape:
            raise ValueError(
                f"Shape of bins {bins_arr.shape} does not match "
                f"edge widths {exp_shape}"
            )
    except Exception as exc:
        raise ValueError(f"Error validating dimensions: {exc}") from None

    # Compute weight grid (product of widths for each bin)
    if ndim == 1:
        weight_grid = widths[0]
    else:
        weight_grid = widths[0]
        for w in widths[1:]:
            weight_grid = np.multiply.outer(weight_grid, w)

    # Compute integral
    return np.sum(bins_arr * weight_grid)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance check
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # If FillRequest is not defined, cannot evaluate
        pass

    # Reject if seq is a Source sequence
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # If Source is not defined, no restriction
        pass

    # Ensure seq is iterable (but not a string/bytes)
    try:
        it = iter(seq)
    except TypeError:
        return False

    # Avoid treating string or bytes as a sequence of FillRequest
    if isinstance(seq, (str, bytes)):
        return False

    # Check for at least one FillRequest element
    try:
        for item in it:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    fill = getattr(obj, "fill", None)
    request = getattr(obj, "request", None)
    return callable(fill) and callable(request)

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return hasattr(obj, 'run') and callable(getattr(obj, 'run'))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        for name in ("fill", "compute"):
            if not hasattr(obj, name):
                return False
            attr = getattr(obj, name)
            if not callable(attr):
                return False
        return True
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both arguments must be dictionaries")
    if level < -1:
        level = -1

    def _diff(a, b, cur_level):
        result = {}
        for k, val in a.items():
            if k not in b:
                # key missing in b: copy the value (take reference if it's a dict)
                result[k] = val
            else:
                val_b = b[k]
                # both values are dicts: recurse if allowed
                if isinstance(val, dict) and isinstance(val_b, dict):
                    # Determine remaining level
                    if cur_level == 0:
                        # max depth reached: compare the dicts as atomic objects
                        if val != val_b:
                            result[k] = val
                    else:
                        # recurse with updated level
                        next_level = cur_level - 1 if cur_level > 0 else -1
                        sub = _diff(val, val_b, next_level)
                        if sub:
                            result[k] = sub
                else:
                    # non-dict values: include if unequal and level==1 or any difference
                    if cur_level == 1:
                        if val != val_b:
                            result[k] = val
                    else:
                        if val != val_b:
                            result[k] = val
        return result

    return _diff(d1, d2, level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Defer import of re to avoid a top‑level import statement
    re = __import__('re')
    KEY_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')
    VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')

    def _format_error(obj, msg):
        """Return an error dict using the string form of the object."""
        return {str(obj): msg}

    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append(_format_error(key, 'expected string or bytes-like object'))
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not KEY_REGEX.fullmatch(key_str):
                messages.append(_format_error(
                    key_str,
                    f"Label key '{key_str}' does not match the regex [{KEY_REGEX.pattern}]"))

        # Recursive check for the value(s)
        def _check_value(v):
            if isinstance(v, (list, tuple)):
                for item in v:
                    _check_value(item)
            else:
                if not isinstance(v, (str, bytes)):
                    messages.append(_format_error(v, 'expected string or bytes-like object'))
                else:
                    val_str = v.decode() if isinstance(v, bytes) else v
                    if not VALUE_REGEX.fullmatch(val_str):
                        messages.append(_format_error(
                            val_str,
                            f"Label value '{val_str}' does not match the regex [{VALUE_REGEX.pattern}]"))

        _check_value(value)

    if messages:
        raise ValidationError(messages)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial ``last_applied_manifest`` list from a
    partial Kubernetes response.

    Args:
        last_applied_manifest (list): The list that will be updated in-place.
        observer_schema (list): A list that describes the expected structure of
            each element in ``response``.  Each item in this list is expected
            to be a dict that may contain a ``type`` key (``'dict'`` or
            ``'list'``) and a ``fields`` key for nested structures.
        response (list): A list of elements returned by the Kubernetes API.
            Each element may be a primitive value, a dict, or another list.

    The function iterates over ``response`` and ensures that each element of
    ``last_applied_manifest`` is populated with the current value.  When an
    element is a ``dict`` or a ``list`` it calls the appropriate helper
    (``update_last_applied_manifest_dict_from_resp`` or this function
    recursively) to update nested structures.

    The function returns ``None`` and mutates ``last_applied_manifest`` in
    place; callers should be prepared for it to be extended (e.g., ``append``)
    when ``response`` contains more items than the current length of
    ``last_applied_manifest``.
    """
    if response is None:
        return

    if not isinstance(response, list):
        raise TypeError(
            f"Expected response to be list, got {type(response).__name__}"
        )

    # Ensure destination list has at least as many elements as the source
    required_len = len(response)
    while len(last_applied_manifest) < required_len:
        last_applied_manifest.append(None)

    for idx, resp_item in enumerate(response):
        # Determine corresponding schema, if available
        schema_item = None
        if idx < len(observer_schema):
            schema_item = observer_schema[idx]
        # If the destination element is None, create appropriate container
        if last_applied_manifest[idx] is None:
            if isinstance(resp_item, dict):
                last_applied_manifest[idx] = {}
            elif isinstance(resp_item, list):
                last_applied_manifest[idx] = []
            else:
                last_applied_manifest[idx] = resp_item
                continue  # Primitive value filled, go to next element

        # If element is a dict, recurse into dict helper
        if isinstance(resp_item, dict):
            if not isinstance(last_applied_manifest[idx], dict):
                raise TypeError(
                    f"Expected dict at index {idx} in last_applied_manifest, "
                    f"got {type(last_applied_manifest[idx]).__name__}"
                )
            # Extract fields from the schema if provided
            child_schema = None
            if isinstance(schema_item, dict):
                child_schema = schema_item.get("fields", [])
            # Delegate to dict helper (assumed to exist in scope)
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], child_schema, resp_item
            )
        # If element is a list, recurse into this list helper
        elif isinstance(resp_item, list):
            if not isinstance(last_applied_manifest[idx], list):
                raise TypeError(
                    f"Expected list at index {idx} in last_applied_manifest, "
                    f"got {type(last_applied_manifest[idx]).__name__}"
                )
            # Extract fields from the schema if provided
            child_schema = None
            if isinstance(schema_item, dict):
                child_schema = schema_item.get("fields", [])
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[idx], child_schema, resp_item
            )
        else:
            # Primitive types: simply overwrite
            last_applied_manifest[idx] = resp_item
    return None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a spec and a manifest attribute
    if not hasattr(app, "spec") or app.spec is None:
        return

    # Initialize the observer_schema dict if it does not exist
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    manifest = getattr(app.spec, "manifest", [])
    # If the manifest is not iterable or empty, nothing to do
    if not isinstance(manifest, (list, tuple)):
        return

    for resource in manifest:
        # Each resource is expected to be a dict representing a Kubernetes object
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            # Skip resources without a kind
            continue

        # Use the resource kind as the key for the observer schema
        # (custom logic may use a composite key if duplicates are possible)
        key = kind

        # If a custom observer schema has already been supplied, skip it
        if key in app.spec.observer_schema:
            continue

        # Build a very generic default observer schema. This can be expanded
        # based on the specific requirements of the application.
        # The goal is to watch the resource's name, namespace, and status
        # conditions, which are commonly used by observers.
        default_schema = {
            "metadata": {
                "name": True,
                "namespace": True,
            },
            "status": {
                "conditions": True,
            },
        }

        # Assign the default schema for this kind
        app.spec.observer_schema[key] = default_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Try to use the class mapping first
    status_key = self.status
    try:
        s = self._STATUS2STR[status_key]
    except Exception:
        # If status is an Enum, try its underlying value
        try:
            s = self._STATUS2STR[getattr(status_key, 'value', status_key)]
        except Exception:
            # Fallback to a generic string representation
            s = str(status_key)
    # Ensure prefix is a string to avoid type errors
    if prefix is None:
        prefix = ''
    return prefix + s

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to locate a log attribute that holds validation messages.
    # Common names include 'log', 'validation_log', or 'messages'.
    for attr in ('log', 'validation_log', 'messages'):
        logs = getattr(self, attr, None)
        if logs is not None:
            break
    else:
        # No known attribute found; return an empty string.
        return ''

    # Normalize the logs to a sequence of strings.
    try:
        if isinstance(logs, (list, tuple)):
            seq = logs
        elif isinstance(logs, dict):
            seq = list(logs.values())
        else:
            seq = [logs]
    except Exception:
        seq = []

    # Build the prefixed string representation.
    lines = []
    for item in seq:
        if item is None:
            continue
        lines.append(f"{prefix}{item}")
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    # Determine spec version
    if extract_spec_version:
        type_val = inventory.get("type")
        allowed_versions = getattr(self, "allowed_spec_versions", ())
        if isinstance(type_val, str) and type_val in allowed_versions:
            spec_version = type_val
        else:
            spec_version = getattr(self, "spec_version", None)
    else:
        spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise ValueError("specification version could not be determined")
    # Store for later use
    self._spec_version = spec_version
    # Run main validation logic
    try:
        return self._run_validation(inventory, spec_version)
    except Exception as exc:
        # Wrap in a more descriptive exception
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if prior is None:
        raise ValueError("prior must be provided and not None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Version comparison (if a version attribute exists)
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is not None and prior_version is not None:
        try:
            # allow comparison of integers, tuples, strings, etc.
            if prior_version > self_version:
                raise ValueError(f"Prior version {prior_version} is newer than current version {self_version}")
        except TypeError:
            # Incomparable types – skip version check
            pass

    # Components to compare: adjust names as appropriate for the inventory
    components = ["species", "processes", "parameters"]
    for comp in components:
        curr_comp = getattr(self, comp, None)
        prior_comp = getattr(prior, comp, None)

        # Skip missing components
        if curr_comp is None or prior_comp is None:
            continue

        # Extract name sets from dicts or iterables
        if isinstance(curr_comp, dict):
            curr_names = set(curr_comp.keys())
        else:
            try:
                curr_names = {item.name for item in curr_comp}
            except AttributeError:
                curr_names = set(curr_comp)

        if isinstance(prior_comp, dict):
            prior_names = set(prior_comp.keys())
        else:
            try:
                prior_names = {item.name for item in prior_comp}
            except AttributeError:
                prior_names = set(prior_comp)

        # Ensure every current item exists in the prior inventory
        missing_names = curr_names - prior_names
        if missing_names:
            raise ValueError(
                f"Prior inventory is missing {comp} entries required by the current inventory: {missing_names}"
            )

    # If no checks raise exceptions, validation passes
    return

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to path data")

    if version not in inventory:
        # No data for this version; return empty map
        return {}

    ver_data = inventory[version]
    if not isinstance(ver_data, dict):
        # Unexpected format; cannot process
        return {}

    path_map = {}
    for logical_path, content in ver_data.items():
        try:
            if isinstance(content, (list, set, tuple)):
                content_set = set(content)
            elif isinstance(content, dict):
                # If content is a dict, take its keys as file identifiers
                content_set = set(content.keys())
            else:
                # Assume singular content identifier
                content_set = {content}
        except Exception:
            # Skip any problematic entries
            continue

        path_map[logical_path] = content_set

    return path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("The fixity block must be a dictionary")

        # The block is expected to contain a 'files' entry mapping file names to
        # dictionaries of hash algorithms and hex digests.
        if 'files' not in fixity:
            raise ValueError("The fixity block must contain a 'files' key")

        files_block = fixity['files']
        if not isinstance(files_block, dict):
            raise ValueError("The 'files' entry must be a dictionary")

        # Ensure all referenced files are present in the manifest.
        for fname, sigs in files_block.items():
            if fname not in manifest_files:
                raise ValueError(f"Fixity references unknown file {fname!r}")

            if not isinstance(sigs, dict):
                raise ValueError(f"The signatures for file {fname!r} must be a dictionary")

            for algo, digest in sigs.items():
                if algo not in ('md5', 'sha1', 'sha256', 'sha512'):
                    raise ValueError(
                        f"Unsupported hash algorithm {algo!r} for file {fname!r}"
                    )
                if not isinstance(digest, str):
                    raise ValueError(
                        f"The digest value for {algo!r} in file {fname!r} must be a string"
                    )
                if not all(c in '0123456789abcdefABCDEF' for c in digest):
                    raise ValueError(
                        f"Digest for {algo!r} in file {fname!r} must be hexadecimal"
                    )

def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, return a single-element list containing the
    absolute path. If `path` is a directory, return a sorted list of
    absolute paths to the regular files contained directly in that
    directory (non-recursive). If `path` does not exist, raise
    FileNotFoundError.
    """
    try:
        # Resolve to absolute path for consistency
        abs_path = os.path.abspath(path)
    except Exception as e:
        raise FileNotFoundError(f"Cannot resolve path '{path}': {e}")

    if not os.path.exists(abs_path):
        raise FileNotFoundError(abs_path)

    if os.path.isfile(abs_path):
        return [abs_path]

    if os.path.isdir(abs_path):
        try:
            files = []
            for entry in os.listdir(abs_path):
                full_entry = os.path.join(abs_path, entry)
                if os.path.isfile(full_entry):
                    files.append(full_entry)
            return sorted(files)
        except Exception as e:
            # If directory listing fails, raise a generic OSError
            raise OSError(f"Failed to list directory '{abs_path}': {e}")

    # In case path exists but is neither a file nor a directory
    raise OSError(f"Unsupported path type: '{abs_path}'")

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError('content must be a string')
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of XPaths
    if isinstance(pubdate_xpaths, (str, bytes)):
        xpaths = [pubdate_xpaths]
    else:
        try:
            xpaths = list(pubdate_xpaths)
        except Exception:
            # If pubdate_xpaths is not iterable, treat it as a single xpath
            xpaths = [pubdate_xpaths]

    # Iterate over the XPaths and return the first found match
    for xpath in xpaths:
        if not xpath:
            continue
        try:
            # Attempt to use lxml's xpath method if available
            matches = node.xpath(xpath) if hasattr(node, 'xpath') else None
            if matches:
                return matches[0]
        except Exception:
            # If xpath evaluation fails, skip to the next
            continue

    # No match found
    return None

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    # Basic validation
    if not isinstance(user, str) or not user.strip():
        raise ValueError("user must be a non-empty string")
    if not isinstance(etcd_host, str) or not etcd_host.strip():
        raise ValueError("etcd_host must be a non-empty string")
    if not isinstance(etcd_port, int):
        try:
            etcd_port = int(etcd_port)
        except (TypeError, ValueError):
            raise ValueError("etcd_port must be an integer")
    if etcd_port <= 0:
        raise ValueError("etcd_port must be a positive integer")

    # Build configuration dictionary
    config = {
        "user": user,
        "etcd_host": etcd_host,
        "etcd_port": etcd_port
    }
    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        import os
        base = os.path.dirname(__file__)
        version_path = os.path.join(base, "version.py")
        with open(version_path, "r") as f:
            for line in f:
                stripped = line.strip()
                if stripped.startswith("__version__"):
                    _, val = stripped.split("=", 1)
                    return val.strip().strip('"\'' )  # remove quotes
    except Exception:
        pass
    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if style is None:
        raise ValueError('style must be provided')
    if not isinstance(style, str):
        raise TypeError('style must be a string')
    style = style.lower()

    # Normalize pieces into a list of (name, version) tuples
    if pieces is None:
        items = []
    elif isinstance(pieces, dict):
        items = list(pieces.items())
    else:
        try:
            items = [tuple(p) for p in pieces]
        except Exception as exc:
            raise TypeError('pieces must be a dict or an iterable of pairs') from exc

    # Rendering logic for supported styles
    if style == 'text':
        return '\n'.join(f'{name}: {version}' for name, version in items)
    elif style == 'json':
        import json
        return json.dumps(
            [{'name': name, 'version': version} for name, version in items],
            indent=2
        )
    elif style == 'yaml':
        try:
            import yaml
        except ImportError as exc:
            raise ImportError('PyYAML is required for yaml style rendering') from exc
        return yaml.safe_dump(
            [{'name': name, 'version': version} for name, version in items],
            sort_keys=False
        )
    elif style == 'xml':
        parts = ['<?xml version="1.0" encoding="UTF-8"?>', '<versions>']
        for name, version in items:
            parts.append(f'  <component name="{name}">')
            parts.append(f'    <version>{version}</version>')
            parts.append('  </component>')
        parts.append('</versions>')
        return '\n'.join(parts)
    else:
        raise ValueError(f'Unsupported style: {style}')

def plus_or_dot(pieces):
    """
    Return a + if we don't already have one, else return a .
    """
    try:
        if '+' in pieces:
            return '.'
        return '+'
    except TypeError:
        raise TypeError("pieces must be an iterable containing elements") from None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Ensure commands is a list of strings
    if isinstance(commands, str):
        # Split the command string into arguments
        cmd_list = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be str, list, or tuple")

    # Append any additional arguments
    if args is not None:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple")
        cmd_list.extend(args)

    # Prepare the subprocess call
    try:
        if verbose:
            print("Executing:", cmd_list)
        stderr = subprocess.DEVNULL if hide_stderr else None
        process = subprocess.Popen(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            shell=False
        )
        stdout, _ = process.communicate()
        if process.returncode != 0:
            raise RuntimeError(f"Command {cmd_list} exited with status {process.returncode}")
        return stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd_list[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command {cmd_list}") from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to retrieve an iterator or list of objects from the hierarchy.
    # Prefer a method named `iter_objects`, fall back to `list_objects` or `get_objects` if available.
    try:
        obj_iter = None
        if hasattr(self, 'iter_objects'):
            obj_iter = self.iter_objects()
        elif hasattr(self, 'list_objects'):
            obj_iter = self.list_objects()
        elif hasattr(self, 'get_objects'):
            obj_iter = self.get_objects()
        else:
            raise AttributeError("No method available to retrieve hierarchy objects")
    except Exception as exc:
        raise RuntimeError("Failed to fetch objects for hierarchy validation") from exc

    for obj in obj_iter:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, 'is_valid'):
                    is_valid = obj.is_valid()
                else:
                    # Fallback: use a 'valid' attribute if present
                    is_valid = getattr(obj, 'valid', True)
            except Exception:
                if show_warnings:
                    print(f"Warning: could not validate object {obj}")
                is_valid = False

        # Check the digest of the object's data if requested
        if is_valid and check_digests:
            try:
                # Retrieve the raw data associated with the object.
                if hasattr(obj, 'get_data'):
                    data = obj.get_data()
                else:
                    data = getattr(obj, 'data', None)

                if data is not None:
                    import hashlib
                    digest = hashlib.sha256(data).hexdigest()
                    if hasattr(obj, 'digest') and digest != obj.digest:
                        if show_warnings:
                            print(f"Warning: digest mismatch for object {obj}")
                        is_valid = False
                else:
                    if show_warnings:
                        print(f"Warning: object {obj} has no data for digest check")
                    is_valid = False
            except Exception:
                if show_warnings:
                    print(f"Warning: could not compute digest for object {obj}")
                is_valid = False

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import json
    from pathlib import Path

    root = Path(self.root_path)

    if root.exists():
        raise FileExistsError(f"The root directory {root} already exists.")
    try:
        root.mkdir(parents=True, exist_ok=False)
        # Create mandatory subdirectories
        objects_dir = root / "objects"
        objects_dir.mkdir()
        latest_dir = root / "latest"
        latest_dir.mkdir()

        # Create a minimal root JSON file
        root_meta = {
            "layout_version": "1.0",
            "objects": [],
            "created_at": self._timestamp(),
        }
        (root / "root.json").write_text(
            json.dumps(root_meta, indent=2), encoding="utf-8"
        )
        return root
    except Exception as exc:
        # Cleanup partially created structure on failure
        for path in root.rglob("*"):
            try:
                if path.is_file():
                    path.unlink()
                else:
                    path.rmdir()
            except Exception:
                pass
        try:
            root.rmdir()
        except Exception:
            pass
        raise IOError(
            f"Failed to initialize OCFL root at {root}: {exc}"
        ) from exc

def _timestamp(self):
    from datetime import datetime
    return datetime.utcnow().isoformat() + "Z"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the
    root inventory so that we can also check them when validating the
    content.

    version_dirs is an array of version directory names and is
    assumed to be in version sequence (1, 2, 3...).

    Returns:
        self
    Raises:
        TypeError: If version_dirs is not a list or tuple.
        FileNotFoundError: If the root or any version inventory file can
            not be located.
        ValueError: If an inventory is missing required entries or
            an entry digest does not match the root digest.
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Initialise a registry of differing digests.  The structure will be:
    #   {version_dir: {path: (root_digest, version_digest)}}
    self.variant_digests = {}

    # Load the root inventory.  The root inventory is expected to be a JSON
    # mapping {path: digest}.  It may be provided directly on ``self`` or
    # stored as ``inventory.json`` inside the root_path.
    if hasattr(self, "root_inventory") and isinstance(self.root_inventory, dict):
        root_inventory = self.root_inventory
    else:
        root_inventory_path = os.path.join(self.root_path, "inventory.json")
        if not os.path.exists(root_inventory_path):
            raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")
        try:
            with open(root_inventory_path, "rt", encoding="utf-8") as f:
                root_inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Could not load root inventory: {exc}") from exc

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a mapping of path to digest")

    for vdir in version_dirs:
        inventory_path = os.path.join(self.root_path, vdir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory for version {vdir} not found at {inventory_path}")
        try:
            with open(inventory_path, "rt", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Could not load inventory for {vdir}: {exc}") from exc

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory for {vdir} must be a mapping of path to digest")

        # Ensure the inventory contains all root entries
        missing = [p for p in root_inventory if p not in inv]
        if missing:
            raise ValueError(f"Inventory for {vdir} missing required entries: {missing}")

        # Find entries whose digest deviates from the root
        diffs = {}
        for path, root_digest in root_inventory.items():
            ver_digest = inv.get(path)
            if root_digest != ver_digest:
                diffs[path] = (root_digest, ver_digest)

        if diffs:
            self.variant_digests[vdir] = diffs

    return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure we are working with a dict
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalise bug_ids into a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    elif isinstance(bug_ids, (list, tuple, set)):
        # leave as is
        pass
    else:
        raise TypeError("bug_ids must be an int, str, list, tuple, or set")

    try:
        ids_str = ','.join(str(b) for b in bug_ids)
    except Exception as exc:
        raise ValueError(f"Unable to convert bug_ids to string: {exc}") from exc

    # If an 'ids' key already exists, merge the values
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, str):
            existing = existing.strip()
        else:
            try:
                existing = ','.join(str(b) for b in existing)
            except Exception:
                existing = ''
        if existing:
            ids_str = f"{existing},{ids_str}"

    params['ids'] = ids_str
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _is_mapping(node):
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'
        except Exception:
            return False

    def _merge_values(lhs, rhs):
        """Deep merge two node values."""
        if _is_mapping(lhs) and _is_mapping(rhs):
            # Merge the inner lists of mapping nodes.
            merged_list = deep_merge_nodes(lhs.value + rhs.value)
            # Construct a new MappingNode; assume the constructor accepts tag and value.
            try:
                return type(lhs)(tag=lhs.tag, value=merged_list)
            except Exception:
                # Fallback: return rhs (last wins) if we cannot construct a new node.
                return rhs
        else:
            # For non-mapping collisions, prefer the right-hand (later) value.
            return rhs

    if not nodes:
        return []

    result = []
    key_index_map = {}
    for key_node, value_node in nodes:
        key_val = getattr(key_node, 'value', None)
        if key_val is None:
            # Skip items with no identifiable key value.
            continue
        if key_val in key_index_map:
            idx = key_index_map[key_val]
            existing_key_node, existing_value_node = result[idx]
            merged_value = _merge_values(existing_value_node, value_node)
            # Keep the original key node for consistency.
            result[idx] = (existing_key_node, merged_value)
        else:
            result.append((key_node, value_node))
            key_index_map[key_val] = len(result) - 1

    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser must not be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected argparse.ArgumentParser instance")
    flags = set()
    for action in actions:
        if hasattr(action, 'option_strings'):
            for opt in action.option_strings:
                if opt:
                    flags.add(opt)
    return ' '.join(sorted(flags)) if flags else ''

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    parser = argparse.ArgumentParser()
    # no specific arguments are defined here; functionality can be extended as needed
    if arguments:
        return parser.parse_args(arguments)
    else:
        import sys
        return parser.parse_args()

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        # Collect option strings from each action that represent flags (start with '-')
        flags = [opt for action in parser._actions for opt in getattr(action, 'option_strings', []) if opt.startswith('-')]
        # Preserve order and remove duplicates
        seen = set()
        unique_flags = []
        for flag in flags:
            if flag not in seen:
                seen.add(flag)
                unique_flags.append(flag)
        return ' '.join(unique_flags)
    except Exception as e:
        raise ValueError(f"Failed to extract flags from parser: {e}") from e

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    try:
        parser = argparse.ArgumentParser()
        # Ensure a subparsers dest is present even if no subparsers are added elsewhere.
        parser.add_subparsers(dest='subparser')
        namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    except Exception as exc:
        raise ValueError(f"Error parsing arguments: {exc}") from exc

    subparser_name = getattr(namespace, 'subparser', None)
    if subparser_name:
        return {subparser_name: namespace}
    return {"global": namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments.
    This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace
    of arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Ensure arguments are processed afresh for each parser
    base_args = list(unparsed_arguments)
    parsed_map = {}
    remaining_map = {}

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(base_args)
            parsed_map[name] = namespace
            remaining_map[name] = remaining
        except Exception:
            # If parsing fails, consider this subparser to have parsed nothing
            parsed_map[name] = None
            remaining_map[name] = base_args

    # Determine which arguments were not claimed by any subparser
    if remaining_map:
        unclaimed = [
            arg for arg in base_args
            if all(arg in rem for rem in remaining_map.values())
        ]
    else:
        unclaimed = base_args

    return parsed_map, unclaimed

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("The 'response' argument cannot be None.")
    if not isinstance(response, (list, tuple)):
        raise TypeError("The 'response' argument must be a list or tuple.")
    if not isinstance(max_results, int):
        raise TypeError("The 'max_results' argument must be an integer.")
    if max_results <= 0:
        raise ValueError("The 'max_results' argument must be a positive integer.")

    # Generator that yields slices of the response
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Re‑raise as a generic exception with context
        raise RuntimeError("Error while paging through the response.") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            continue  # ignore non-dict entries
        for k, v in d.items():
            if k in result:
                try:
                    result[k] += v
                except TypeError:
                    raise TypeError(
                        f"Cannot sum values for key {k!r}: {result[k]!r} + {v!r}"
                    )
            else:
                result[k] = v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        raise TypeError('url must be a string')

    if not isinstance(url_args, dict):
        raise TypeError('url_args must be a mapping/dict')

    # Iterate over all key/value pairs and replace placeholders in the URL.
    # Placeholders are expected to be in the form '{key}'.
    result = url
    for key, value in url_args.items():
        # Ensure the key is a string.
        key_str = str(key)
        # Encode the value for URL safety. Treat None as empty string.
        if value is None:
            encoded_val = ''
        else:
            encoded_val = urllib.parse.quote_plus(str(value))
        placeholder = '{' + key_str + '}'
        result = result.replace(placeholder, encoded_val)

    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ("none", "null", "n/a", "na"):
            return True
    return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if not hasattr(parser, "_actions"):
        raise TypeError(f"Expected an argparse.ArgumentParser, got {type(parser)!r}")
    flags = []
    for action in parser._actions:
        # action.option_strings contains optional flag strings (e.g., ["-h", "--help"])
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)
    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list or tuple")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, remainder = divmod(n, base)
            digits.append(alphabet[remainder])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def replace_dots(value, arg):
    """
    Replaces all values of '.' to arg from the given string

    :param value: The input string to modify
    :type value: str
    :param arg: The string that will replace each '.'
    :type arg: str
    :return: The modified string
    :rtype: str
    """
    if value is None:
        raise ValueError("value cannot be None")
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if arg is None:
        raise ValueError("arg cannot be None")
    if not isinstance(arg, str):
        try:
            arg = str(arg)
        except Exception as exc:
            raise TypeError("arg must be convertible to a string") from exc
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("cls must be a class")
    result = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        for sub in parent.__subclasses__():
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")

    base = len(alphabet)
    inverse_alphabet = {}
    for idx, symbol in enumerate(alphabet):
        if symbol in inverse_alphabet:
            raise ValueError(f"Duplicate symbol {symbol!r} in alphabet")
        inverse_alphabet[symbol] = idx

    n = 0
    for ch in string:
        if ch not in inverse_alphabet:
            raise ValueError(f"Character {ch!r} not found in alphabet")
        n = n * base + inverse_alphanum[ch]

    return n

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems, including macOS
        return os.uname().sysname == "Darwin"
    except AttributeError:
        # os.uname may not exist (e.g., on Windows); fall back to sys.platform
        import sys
        return sys.platform.lower().startswith("darwin")
    except Exception:
        # Any unexpected error should result in False
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) <= 1:
        return name
    # Handle double quotes with possible escaped quotes
    if name.startswith('"') and name.endswith('"'):
        return name[1:-1].replace('\\\\', '\\').replace('\\"', '"')
    # Handle single quotes
    if name.startswith("'") and name.endswith("'"):
        return name[1:-1].replace("\\'", "'")
    # Handle angle brackets
    if name.startswith('<') and name.endswith('>'):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Basic type validation
    if not isinstance(s, (str, bytes)):
        raise TypeError('split() expects a string or bytes')
    # Convert binary to text for py3, no-op on py2
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception as exc:  # pragma: no cover
            raise ValueError('Unable to decode bytes to UTF-8') from exc
    import shlex
    import sys
    # Determine the posix flag based on the platform argument
    if platform == 'this':
        posix = not sys.platform.lower().startswith('win')
    elif platform in (1, 'posix'):
        posix = True
    elif platform in (0, 'win', 'windows'):
        posix = False
    else:
        raise ValueError('unknown platform: %r' % platform)
    # Use shlex with the appropriate posix flag
    return shlex.split(s, posix=posix)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '-i', '--exclude-standard'],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
    except subprocess.CalledProcessError as exc:
        # If git fails, return an empty string or you could log the error
        return ''
    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        # Resolve all address types for the given host
        infos = socket.getaddrinfo(host, None, 0, 0, 0, socket.AI_PASSIVE)
    except socket.gaierror:
        # If we can't resolve, assume it's not local
        return False

    for info in infos:
        family, _, _, _, sockaddr = info
        try:
            if family == socket.AF_INET:
                ip_addr = sockaddr[0]
                # IPv4 loopback: 127.0.0.0/8
                if ip_addr.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip_addr = sockaddr[0]
                # IPv6 loopback: ::1 (may include zone index)
                if ip_addr == "::1" or ip_addr.split("%", 1)[0] == "::1":
                    return True
        except Exception:
            # Ignore malformed address info
            continue
    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    Example:
        ['foo.txt', 'pp:root/somedir'] -> ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        raise TypeError("find_paths cannot be None")
    if not isinstance(find_paths, (list, tuple)):
        raise TypeError(f"find_paths must be a list or tuple, got {type(find_paths)}")
    result = []
    for item in find_paths:
        if not isinstance(item, str):
            raise TypeError(f"Each find_path must be a string, got {type(item)}")
        # Patterns are identified by presence of ':' (e.g., 'pp:root/somedir')
        if ':' in item:
            result.append(item)
        else:
            # Convert fragment into a glob pattern
            result.append(f"sh:**/*{item}*/**")
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name == 'nt':
            ostype = os.environ.get('OSTYPE', '').lower()
            msystem = os.environ.get('MSYSTEM', '').lower()
            if 'msys' in ostype or 'mingw' in ostype or 'msys' in msystem or 'mingw' in msystem:
                return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, (str, bytes)):
        raise TypeError("rendered_config must be a string or bytes")
    config_path = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_path):
        # Abort to avoid overwriting
        return
    dir_name = os.path.dirname(config_path)
    if dir_name and not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            if not os.path.isdir(dir_name):
                raise  # re-raise if failed to create required directory
    try:
        with open(config_path, "w" if isinstance(rendered_config, str) else "wb") as f:
            f.write(rendered_config)
        # Set the file mode if applicable
        try:
            os.chmod(config_path, mode)
        except OSError:
            # Some filesystems may ignore chmod; ignore silently
            pass
    except Exception as exc:
        # Propagate any unexpected I/O errors
        raise exc

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract name and default from various possible matcher representations
    if hasattr(matcher, "name"):
        name = matcher.name
        default_present = hasattr(matcher, "default")
        default = getattr(matcher, "default", None) if default_present else None
    elif hasattr(matcher, "groupdict"):
        attrs = matcher.groupdict()
        if "name" not in attrs:
            raise AttributeError("Matcher groupdict must contain a 'name' key")
        name = attrs["name"]
        default_present = "default" in attrs
        default = attrs.get("default")
    elif isinstance(matcher, dict):
        if "name" not in matcher:
            raise KeyError("Matcher dict must contain a 'name' key")
        name = matcher["name"]
        default_present = "default" in matcher
        default = matcher.get("default")
    else:
        raise TypeError("Matcher must be an object with a 'name' attribute, a regex match object, or a dict containing 'name'")

    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")

    value = os.environ.get(name)
    if value is not None:
        return value
    if default_present:
        return default
    raise KeyError(f"Environment variable '{name}' is not set and no default was provided")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # If we already have a compiled pattern, simply return it
    if isinstance(pattern, re.Pattern):
        return pattern
    # Ensure the input is a string
    if not isinstance(pattern, str):
        raise TypeError(f"Expected a string or compiled pattern, got {type(pattern).__name__}")
    # Optionally strip surrounding whitespace
    if strip:
        pattern = pattern.strip()
    # Compile the string into a regex pattern
    return re.compile(pattern)

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        ipaddress.IPv4Address(target)
    except (ipaddress.AddressValueError, ValueError):
        return False
    return True

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper:
            return yaml.safe_dump(obj, Dumper=dumper)
        return yaml.safe_dump(obj)
    except yaml.YAMLError as exc:
        raise ValueError(f'Failed to dump object to YAML: {exc}') from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import logging

    # Helper to resolve environment variables in configuration values
    def _resolve_env_vars(value):
        if isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_vars(v) for v in value]
        elif isinstance(value, str):
            return os.path.expandvars(value)
        else:
            return value

    results = {}
    error_records = []

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")
            ext = os.path.splitext(filename)[1].lower()
            with open(filename, 'r', encoding='utf-8') as fp:
                if ext == '.json':
                    config = json.load(fp)
                elif ext in {'.yaml', '.yml'}:
                    import yaml
                    config = yaml.safe_load(fp)
                elif ext == '.toml':
                    import toml
                    config = toml.load(fp)
                else:
                    raise ValueError(f"Unsupported configuration file extension: {ext}")
            if overrides:
                if isinstance(config, dict):
                    config.update(overrides)
                else:
                    raise TypeError("Configuration is not a dictionary; cannot apply overrides.")
            if resolve_env:
                config = _resolve_env_vars(config)
            results[filename] = config
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            error_records.append(record)

    return results, tuple(error_records)

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")
        # Retrieve the mapping of protocol versions to handler classes.
        # This mapping is expected to be defined on the class as
        #   _protocol_handlers = { (major, minor): HandlerClass, ... }
        handler_map = getattr(cls, "_protocol_handlers", {})
        if protocol_version is None:
            # Return a copy of the full mapping.
            return dict(handler_map)
        # Return the handler for the requested version if it exists.
        if protocol_version in handler_map:
            return {protocol_version: handler_map[protocol_version]}
        return {}

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        :returns: Bookmarks instance
        """
        if values is None:
            raise ValueError("values must not be None")

        try:
            raw_list = list(values)
        except TypeError as e:
            raise TypeError("'values' must be an iterable") from e

        processed = []
        for val in raw_list:
            if not isinstance(val, str):
                raise TypeError(f"Bookmark value must be a string, got {type(val).__name__}")
            try:
                val.encode('ascii')
            except UnicodeEncodeError as e:
                raise ValueError(f"Bookmark value must be ASCII: {val!r}") from e
            processed.append(val)

        # Assume the constructor takes a list of bookmark strings
        return cls(processed)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a list or tuple, return it unchanged along with its type.
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))
    # Attempt to get an iterator; raise a meaningful error if not iterable.
    try:
        iterator = iter(seq)
    except TypeError:
        raise TypeError(f"Object of type {type(seq).__name__} is not iterable")
    # Consume the iterator, respecting bufsize if provided.
    if bufsize is not None:
        seq_list = []
        for i, element in enumerate(iterator):
            if i >= bufsize:
                break
            seq_list.append(element)
        return (seq_list, list)
    return (list(iterator), list)

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Import numpy locally to avoid global dependencies
    try:
        import numpy as np  # noqa: F401
    except Exception:
        np = None

    # Helper to check numeric
    def _is_numeric(val):
        if np:
            return isinstance(val, (int, float, np.integer, np.floating))
        return isinstance(val, (int, float))

    # If no argument, simply return current scale
    if other is None:
        # Prefer attribute `_scale` if present, else try property `scale`
        return getattr(self, "_scale", getattr(self, "scale", None))

    # Validate that other is numeric
    if not _is_numeric(other):
        raise TypeError("Expected a numeric value for the target scale, got %r" % (other,))

    # Retrieve current scale
    current_scale = getattr(self, "_scale", getattr(self, "scale", None))
    if current_scale is None or _is_numeric(current_scale) and current_scale == 0:
        # Raise the specific exception expected by the docstring; fall back to ValueError if not defined
        try:
            raise LenaValueError("Cannot rescale graph with unknown or zero current scale.")
        except NameError:
            raise ValueError("Cannot rescale graph with unknown or zero current scale.")

    # Compute scaling factor
    factor = float(other) / float(current_scale)

    # Determine the last coordinate (assuming the graph stores coordinate names in a list or tuple)
    coord_names = getattr(self, "coord_names", None)
    if coord_names is not None and len(coord_names) > 0:
        last_coord = coord_names[-1]
    else:
        # Fallback: try to extract from field names that are coordinate-like (e.g., last key)
        fields = getattr(self, "fields", {})
        if isinstance(fields, dict) and fields:
            last_coord = list(fields.keys())[-1]
        else:
            last_coord = None

    # Rescale fields and errors for the last coordinate if applicable
    if last_coord is not None:
        # Rescale field values
        if hasattr(self, "fields"):
            try:
                self.fields[last_coord] = self.fields[last_coord] * factor
            except Exception:
                # In case fields are not subscriptable or contain non-numeric values
                pass
        # Rescale errors if present
        if hasattr(self, "errors"):
            try:
                self.errors[last_coord] = self.errors[last_coord] * factor
            except Exception:
                pass

    # Update the stored scale to the new value
    setattr(self, "_scale", other)

    # Typically a setter returns None; but for convenience return the new scale
    return other

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")

    # Determine if candidate is a class or an instance
    if isinstance(candidate, type):
        # Check subclass relationship
        if not issubclass(candidate, iface):
            if tentative:
                return False
            raise TypeError(f"Candidate class {candidate.__name__} does not inherit from interface {iface.__name__}")
        candidate_obj = candidate
    else:
        # Check instance relationship
        if not isinstance(candidate, iface):
            if tentative:
                return False
            raise TypeError(f"Candidate instance {candidate!r} does not satisfy interface {iface.__name__}")
        candidate_obj = candidate.__class__

    # If the interface specifies abstract methods, ensure they're implemented
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        implemented = set(dir(candidate_obj))
        missing = abstract_methods - implemented
        if missing:
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate_obj.__name__} is missing implementation of abstract methods: "
                f"{', '.join(sorted(missing))}"
            )

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if not bases:
        raise TypeError("At least one base class must be provided")

    # Gather the metaclasses of all base classes
    metaclasses = [type(b) for b in bases]

    # Include the explicit metaclass if provided
    if explicit_mc is not None:
        # explicit_mc may be a tuple or list (for multiple metaclasses)
        if isinstance(explicit_mc, (tuple, list)):
            metaclasses.extend(explicit_mc)
        else:
            metaclasses.append(explicit_mc)

    # Remove duplicates while preserving order
    seen = set()
    unique_metaclasses = []
    for mc in metaclasses:
        if mc not in seen:
            seen.add(mc)
            unique_metaclasses.append(mc)

    # Find the most derived common metaclass
    most_derived = unique_metaclasses[0]
    for next_mc in unique_metaclasses[1:]:
        try:
            if issubclass(next_mc, most_derived):
                most_derived = next_mc
            elif not issubclass(most_derived, next_mc):
                raise TypeError(
                    f"Incompatible metaclasses {most_derived!r} and {next_mc!r}"
                )
            # else keep most_derived
        except TypeError as exc:
            # issubclass may raise if either is not a class
            raise TypeError(f"Invalid metaclass encountered: {exc}") from exc

    return most_derived

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # If key is missing, decide what to return / raise
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)

    # Attempt to find and pop the key from the appropriate internal map
    for map_obj in (self._pb.IntMap,
                    self._pb.FloatMap,
                    self._pb.StringMap,
                    self._pb.BoolMap):
        if key in map_obj:
            return map_obj.pop(key)
    # In case the key is present in self but not in any sub-map (unlikely),
    # raise a KeyError to be consistent with dict behaviour
    raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # If the dict is empty, raise a KeyError
    try:
        if len(self) == 0:
            raise KeyError('dict is empty')
    except Exception:
        raise KeyError('dict is empty')

    # Determine which attribute holds the frequency mapping
    freq_map = getattr(self, '_freq', None) \
               or getattr(self, '_frequency', None) \
               or getattr(self, 'frequency', None)
    if freq_map is None:
        raise AttributeError('Frequency map attribute not found')

    # Find the minimum frequency
    try:
        min_freq = min(freq_map.values())
    except Exception:
        raise KeyError('dict is empty')

    # Get a key with that minimum frequency
    candidate_key = None
    for key, f in freq_map.items():
        if f == min_freq:
            candidate_key = key
            break

    if candidate_key is None:
        raise KeyError('dict is empty')

    # Remove the key from the underlying storage
    value = self.pop(candidate_key)

    # Remove the key from the frequency map
    freq_map.pop(candidate_key, None)

    return (candidate_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Try to use an internal OrderedDict that maintains recency.
    try:
        return self._lru.popitem(last=False)
    except AttributeError:
        # Fallback: assume the object itself behaves as a dict.
        try:
            key = next(iter(self))
        except StopIteration:
            raise KeyError('LRU cache is empty') from None
        value = self[key]
        del self[key]
        return key, value
    except KeyError:
        # Internal OrderedDict was empty.
        raise KeyError('LRU cache is empty') from None

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self, last=True)
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")
    except Exception as e:
        raise RuntimeError(f"Unable to pop item: {e}") from e

def _create_in_regex(self) -> Pattern:
        """
        Create the in-style parameter regular expression.

        Returns the in-style parameter regular expression (:class:`re.Pattern`).
        """
        # The in-style parameter is identified by the word "in",
        # possibly surrounded by word boundaries.  We ignore case and
        # keep the Unicode flag for Python 3.
        pattern = r'\bin\b'
        try:
            return re.compile(pattern, flags=re.IGNORECASE | re.UNICODE)
        except re.error as exc:
            raise ValueError(f"Failed to compile 'in' regex: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        data = json.loads(body_str)
        if "encrypted_magic_envelope" in data or "magic_envelope" in data:
            return True
    except Exception:
        pass

    # Public XML payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        xml = etree.fromstring(body_str.encode("utf-8"))
        if xml.tag in ("MAGIC_ENV", "Patron", "Legacy"):
            return True
    except Exception:
        pass

    # Legacy plain text indicator
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        if "legacy-diaspora" in body_str.lower():
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.

    Matrix requests typically have a URI path that starts with "/_matrix",
    use "application/json" as the content type, and include a Bearer token
    in the "Authorization" header. This function checks for those
    characteristics in a few common ways to accommodate different web
    frameworks.

    Args:
        request: A request object, usually a dictionary or an object
                 with attributes such as ``path``, ``headers``, and
                 ``CONTENT_TYPE``.

    Returns:
        bool: ``True`` if the request looks like a Matrix request,
              otherwise ``False``.
    """
    # Attempt to determine the request path
    path = None
    try:
        if isinstance(request, dict):
            path = request.get("path") or request.get("PATH_INFO")
        else:
            path = getattr(request, "path", None) or getattr(request, "PATH_INFO", None)
    except Exception:
        # Failed to get path; continue to other checks
        pass

    # Check for the typical Matrix path prefix
    if path and path.startswith("/_matrix"):
        return True

    # Attempt to read the content type
    content_type = None
    try:
        if isinstance(request, dict):
            content_type = request.get("Content-Type") or request.get("CONTENT_TYPE")
        else:
            content_type = getattr(request, "content_type", None) or getattr(request, "CONTENT_TYPE", None)
            # Some frameworks expose headers in a dict under `headers`
            if content_type is None and hasattr(request, "headers"):
                content_type = request.headers.get("Content-Type")
    except Exception:
        pass

    if content_type and content_type.lower().startswith("application/json"):
        return True

    # Attempt to read the Authorization header for a Bearer token
    auth_header = None
    try:
        if isinstance(request, dict):
            auth_header = request.get("Authorization") or request.get("HTTP_AUTHORIZATION")
        else:
            auth_header = getattr(request, "authorization", None) or getattr(request, "HTTP_AUTHORIZATION", None)
            if auth_header is None and hasattr(request, "headers"):
                auth_header = request.headers.get("Authorization")
    except Exception:
        pass

    if auth_header and auth_header.lower().startswith("bearer "):
        return True

    # If none of the heuristics matched, return False
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    from datetime import datetime, timezone
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    # Ensure the datetime is UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    # Return ISO 8601 string without microseconds and with trailing Z
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Find URLs and convert them to anchor tags with target=_blank.
    # We assume the caller has `re` imported or it's available in the module scope.
    _URL_RE = re.compile(r'\b(https?://[^\s]+)')
    def _replace(match):
        url = match.group(1)
        # Return a link with target="_blank" attribute to open in a new tab.
        return f'<a href="{url}" target="_blank">{url}</a>'
    return _URL_RE.sub(_replace, text)

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' must be a string")
    tag = tag.strip()
    if not tag:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Guard against a None or null node
    if node is None:
        return {}

    result = {}
    # Try to iterate over the children; if the node is not an iterable element,
    # return an empty dictionary to avoid raising an exception.
    try:
        for child in node:
            # Use the tag name as the key.  Preserve the full tag including
            # namespaces if present – callers can strip them if desired.
            tag = child.tag
            if tag in result:
                # If we've already stored this tag, make sure the value is a list.
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception:
        # If for some reason the node is not iterable as expected, just return
        # an empty dictionary instead of propagating the exception.
        return {}

    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")

    # Default path if none provided
    if document_path is None:
        document_path = "/.well-known/nodeinfo/1.0"

    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Strip any trailing slash from the base url to avoid double slashes
    base = url.rstrip("/")

    href = base + document_path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        data = json.loads(document)
        return data
    except Exception:
        pass  # fall back to XRD

    # Attempt to parse XRD (XML)
    try:
        # ElementTree is assumed to be imported elsewhere
        root = ElementTree.fromstring(document)
    except Exception:
        # If parsing fails, return empty dict
        return {}

    result: Dict[str, Any] = {}

    # Subject element
    subject = root.findtext('Subject')
    if subject:
        result['subject'] = subject

    # Find all Link elements
    links = root.findall('Link')
    for link in links:
        rel = link.attrib.get('rel')
        href = link.attrib.get('href')
        if not rel or not href:
            continue

        rel_lower = rel.lower()
        if rel_lower == 'hcard':
            result['hcard_url'] = href
        elif rel_lower == 'self':
            result['self_url'] = href
        elif rel_lower == 'lrdd':
            result['lrdd_url'] = href
        else:
            # store other rels in a dict of lists
            result.setdefault('links', {}).setdefault(rel, []).append(href)

    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split('@', 1)[1]
    except Exception:
        return None
    import urllib.request, urllib.parse, urllib.error
    url = f"https://{host}/.well-known/webfinger?resource=acct:{urllib.parse.quote(handle)}"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except (urllib.error.URLError, urllib.error.HTTPError, Exception):
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    # Normalise settings_dirs to a list of directories
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            dirs = []

    found_files = []
    for dir_path in dirs:
        if not os.path.isdir(dir_path):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                # If spec_option is None or empty, match everything
                pattern = spec_option or '*'
                if fnmatch.fnmatch(entry, pattern):
                    found_files.append(full_path)
        except OSError:
            # Skip directories that can't be accessed
            continue

    return sorted(found_files)

def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        try:
            # Import ansible constants module which provides configuration handling
            from ansible import constants as ansible_constants
