def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("No spec content provided")

    # If spec_content is already a dict, skip parsing
    if isinstance(spec_content, dict):
        data = spec_content
    else:
        try:
            # Assumes yaml.safe_load is available in the context
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Error parsing YAML content: {exc}")

    if not isinstance(data, dict):
        raise IRValidatorException(f"Spec content must be a mapping object, got {type(data).__name__}")

    # Define the mandatory fields for the spec
    required_fields = ["name", "type", "version"]
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing mandatory fields in spec: {', '.join(missing)}")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Ensure a file path was provided
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    # Load the YAML file
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except IOError as e:
        raise IRValidatorException(f"Error reading file {yaml_file}: {e}") from e
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}") from e

    if data is None:
        raise IRValidatorException(f"No data found in YAML file {yaml_file}")

    # Validate mandatory fields if they are defined on the class
    mandatory_fields = getattr(cls, "mandatory_fields", None)
    if mandatory_fields:
        missing = [fld for fld in mandatory_fields if fld not in data or data[fld] in (None, "")]
        if missing:
            raise IRValidatorException(
                f"Mandatory fields missing in {yaml_file}: {', '.join(missing)}"
            )

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Create a new dictionary that will contain all resolved groups.
    resolved = {}
    # Keep track of groups that have already been processed to avoid recursion loops.
    visited = set()

    def _resolve_group(name):
        """Recursively resolve a single group name."""
        if name in visited:
            raise ValueError(f'Circular include reference detected for group: {name}')
        visited.add(name)

        if name not in parser_dict:
            raise KeyError(f'Included group "{name}" not found in parser_dict')

        # Make a shallow copy so we don't mutate the original structures.
        group_dict = dict(parser_dict[name])

        # Resolve any nested includes in this group.
        nested_includes = group_dict.pop('include', None)
        if nested_includes:
            if not isinstance(nested_includes, (list, tuple)):
                raise TypeError(f'Include value for group "{name}" must be a list or tuple')
            for sub_name in nested_includes:
                _resolve_group(sub_name)

        # Merge the group's arguments into the resolved dict, preserving existing keys.
        for key, value in group_dict.items():
            if key in resolved and resolved[key] is not None:
                continue  # Existing key takes precedence.
            resolved[key] = value

    # First, handle any top‑level include directive.
    top_level_includes = parser_dict.pop('include', None)
    if top_level_includes:
        if not isinstance(top_level_includes, (list, tuple)):
            raise TypeError('Top‑level include must be a list or tuple')
        for inc_name in top_level_includes:
            _resolve_group(inc_name)

    # Process all remaining groups in the dictionary.
    for group_name in list(parser_dict.keys()):
        # Skip items that are not groups (e.g., simple arguments).
        if not isinstance(parser_dict[group_name], dict):
            continue
        _resolve_group(group_name)

    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Iterate over all arguments defined for this instance
    for arg in getattr(self, "args", []):
        # Only consider objects that are valid option specifications
        if not isinstance(arg, _BaseOpt):
            continue

        # Start with the option's intrinsic default (if any)
        val = None
        if not isinstance(arg.default, NoDefault):
            val = arg.default

        # Attempt to override the value with what's present in the spec
        # `spec` may be a dict-like object or an attribute container
        spec_val = None
        try:
            spec_val = getattr(self.spec, arg.name, None)
        except Exception:
            # If attributes are not available, fall back to dict access
            try:
                spec_val = self.spec.get(arg.name)
            except Exception:
                spec_val = None

        if spec_val not in (None, {}):
            val = spec_val

        # For dictionary options, merge nested defaults from the
        # corresponding scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                if val is None:
                    val = {}
                # Ensure we do not overwrite non-dict defaults
                if isinstance(val, dict):
                    val.update(nested)
                else:
                    val = nested

        if val is not None:
            defaults[arg.name] = val

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {
        "old_option": "new_option",
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings
    # Mapping from deprecated argument names to their replacements.
    # Expected to be defined as a class attribute; fall back to empty dict if absent.
    deprecated_map = getattr(self, 'deprecated_arg_map', {})
    if not isinstance(deprecated_map, dict):
        deprecated_map = {}

    def _warn_deprecated(source_name, args_dict):
        if args_dict is None:
            return
        for key in args_dict:
            if key in deprecated_map:
                warnings.warn(
                    f"Argument '{key}' is deprecated (found in {source_name}); "
                    f"use '{deprecated_map[key]}' instead.",
                    DeprecationWarning,
                    stacklevel=3,
                )

    _warn_deprecated("CLI", cli_args)
    _warn_deprecated("Answer file", answer_file_args)

    # Additionally flag if the same deprecated argument appears in both sources
    cli_deprecated = {k for k in (cli_args or {}) if k in deprecated_map}
    ans_deprecated = {k for k in (answer_file_args or {}) if k in deprecated_map}
    for dup in cli_deprecated & ans_deprecated:
        warnings.warn(
            f"Deprecated argument '{dup}' found in both CLI and answer file; "
            "this may be confusing.",
            DeprecationWarning,
            stacklevel=3,
        )

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Basic input validation
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Ensure the object contains a command specification mapping
        if not hasattr(self, "command_specs"):
            raise AttributeError(
                "The object does not contain a 'command_specs' attribute"
            )

        # Retrieve the specification for the requested command
        cmd_spec = self.command_specs.get(command_name)
        if cmd_spec is None:
            raise KeyError(f"No command specification found for '{command_name}'")

        # Prefer returning the pre‑stored 'options' list if available
        options = cmd_spec.get("options")
        if options is not None:
            if not isinstance(options, (list, tuple)):
                raise TypeError(
                    f"The 'options' entry for '{command_name}' must be a list or tuple"
                )
            return list(options)

        # Fall back to extracting options from a parser object if present
        parser = cmd_spec.get("parser")
        if parser is not None:
            try:
                # This is a best‑effort attempt; the exact attribute may differ
                opt_list = getattr(parser, "option_list", None) or getattr(parser, "options", None)
                if opt_list is None:
                    raise ValueError
                return list(opt_list)
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to extract options from the parser for '{command_name}': {exc}"
                ) from exc

        # If neither 'options' nor a parser are available, return an empty list
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if command_name not in self.commands:
            return None
        command_options = self.commands[command_name]
        return command_options.get(argument_name)
    except Exception as exc:
        if hasattr(self, 'logger'):
            self.logger.exception("Failed to get option spec for %s:%s", command_name, argument_name)
        return None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, 'required_args', getattr(self, 'required', []))
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values.")
    for name in required:
        if name not in args or args[name] is None:
            raise ValueError(f"Missing required argument: {name}")
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from parsed YAML.
    arg_specs = self.parsed_yaml.get('args', {})
    # Accept either a dict or a list of (name, value) pairs.
    if isinstance(args, list):
        args = dict(args)
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or a list of (name, value) pairs")
    for arg_name, value in args.items():
        spec = arg_specs.get(arg_name, {})
        max_len = spec.get('length')
        # Skip if no length constraint is defined.
        if max_len is None:
            continue
        # Ensure the value supports len().
        try:
            actual_len = len(value)
        except Exception as exc:
            raise ValueError(f"Argument '{arg_name}' does not support len()") from exc
        if actual_len > max_len:
            raise ValueError(f"Length of argument '{arg_name}' ({actual_len}) exceeds maximum allowed ({max_len})")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    # Prefer the attribute that holds argument definitions; fallback to options
    defs = getattr(self, 'argument_definitions', None)
    if defs is None:
        defs = getattr(self, 'options', {})
    for argname, value in args.items():
        if value is None:
            continue
        definition = defs.get(argname)
        if not definition:
            continue
        choices = definition.get('choices')
        if not choices:
            continue
        # If value is an iterable (list/tuple/set), check each element
        if isinstance(value, (list, tuple, set)):
            for item in value:
                if item not in choices:
                    raise ValueError(
                        f"Argument '{argname}' has invalid value '{item}'. "
                        f"Available choices are {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Argument '{argname}' has invalid value '{value}'. "
                    f"Available choices are {choices}"
                )
    # return None to indicate success
    return None

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the object has min_ and max_ attributes
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError("Instance must define 'min_' and 'max_' attributes for validation")
    min_val, max_val = getattr(self, "min_"), getattr(self, "max_")

    if min_val is None or max_val is None:
        raise ValueError("'min_' and 'max_' must not be None")
    if min_val > max_val:
        raise ValueError("'min_' must be less than or equal to 'max_'")

    # Normalize input arguments: support dict or iterable of values
    if isinstance(args, dict):
        items = args.items()
    else:
        # Treat as sequence of values; use index as key
        items = enumerate(args)

    for key, val in items:
        if val is None:
            # Skip None values unless explicitly required
            continue
        try:
            # Attempt to cast to a numeric type for comparison
            numeric_val = float(val)
        except (TypeError, ValueError):
            # Non-numeric values are ignored; adjust logic if needed
            continue
        if not (min_val <= numeric_val <= max_val):
            raise ValueError(
                f"Argument '{key}' value {numeric_val} is outside the allowed "
                f"range [{min_val}, {max_val}]"
            )
    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic input validation
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")

        # If spec_option is callable we assume it is already the type factory.
        if callable(spec_option):
            type_factory = spec_option
        else:
            # Default parsing parameters
            delimiter = ","
            element_type = str

            # Parse spec_option if it is a mapping or string
            if isinstance(spec_option, dict):
                delimiter = spec_option.get("delimiter", delimiter)
                elem = spec_option.get("element_type", element_type)
                if isinstance(elem, str):
                    if elem.lower() == "int":
                        element_type = int
                    elif elem.lower() == "float":
                        element_type = float
                    elif elem.lower() == "str":
                        element_type = str
                    else:
                        raise ValueError(f"Unsupported element_type: {elem}")
                elif callable(elem):
                    element_type = elem
                else:
                    raise ValueError("element_type must be a str or callable")
            elif isinstance(spec_option, str):
                # Try to interpret the string as an element type
                elem = spec_option.lower()
                if elem == "int":
                    element_type = int
                elif elem == "float":
                    element_type = float
                elif elem == "str":
                    element_type = str
                else:
                    # Treat as custom element type name; attempt to resolve
                    try:
                        element_type = eval(elem, {"__builtins__": {}})
                    except Exception:
                        raise ValueError(f"Unsupported spec_option string: {spec_option}")
            else:
                raise ValueError("spec_option must be a callable, dict, or string")

            # Build a parsing function based on the resolved parameters
            def type_factory(value):
                try:
                    parts = [p.strip() for p in value.split(delimiter)]
                    return [element_type(p) for p in parts]
                except Exception as exc:
                    raise ValueError(f"Failed to parse complex argument for {option_name}: {exc}") from exc

        # Provide a name for debugging or introspection
        type_factory.__name__ = f"{subcommand}_{option_name}_{type_name}"
        return type_factory

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Guard against non-dict input
    if not isinstance(args, dict):
        return {}, {}

    # Determine the set of keys that should be considered control arguments.
    # If the instance defines a collection of control keys, use it; otherwise
    # fall back to an empty set. Concrete subclasses may provide a suitable
    # attribute (e.g., ``self.control_args``) to customize this behavior.
    try:
        control_keys = getattr(self, 'control_args', None)
        if isinstance(control_keys, (list, tuple, set)):
            control_keys = set(control_keys)
        else:
            # If the attribute is defined but not iterable, ignore it.
            control_keys = set()
    except Exception:
        control_keys = set()

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        return  # nothing to do if values_dict is not a dict

    # Helper to coerce a single value
    def _coerce(val):
        # Already a non-string, keep as is
        if not isinstance(val, str):
            return val
        # Try boolean
        if val.lower() in {"true", "t", "yes", "y", "1"}:
            return True
        if val.lower() in {"false", "f", "no", "n", "0"}:
            return False
        # Try integer
        try:
            if val.lstrip("-").isdigit():
                return int(val)
        except Exception:
            pass
        # Try float
        try:
            return float(val)
        except Exception:
            pass
        # Try comma‑separated list
        if "," in val:
            parts = [p.strip() for p in val.split(",")]
            # Coerce each part recursively
            return [_coerce(p) for p in parts]
        # Default: keep as string
        return val

    # Iterate over a list of keys to avoid dict size change during iteration
    for key in list(values_dict.keys()):
        values_dict[key] = _coerce(values_dict[key])

    # Return the modified dictionary for convenience
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    The function looks for a ``plugin.json`` or ``plugin.yaml`` file inside the
    supplied ``plugin_dir``.  The content of the file is parsed and flattened
    into a single dictionary, where nested keys are joined with a dot.  Lists
    are flattened using numeric indices.

    :param plugin_dir: A path to the plugin's directory.
    :return: A flatten dictionary that contains the plugin's properties.
    """
    import os
    import json

    # Helper function that recursively flattens a nested structure.
    def _flatten(value, prefix, result):
        if isinstance(value, dict):
            for k, v in value.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(v, new_prefix, result)
        elif isinstance(value, list):
            for idx, item in enumerate(value):
                new_prefix = f"{prefix}.{idx}" if prefix else str(idx)
                _flatten(item, new_prefix, result)
        else:
            result[prefix] = value

    spec_file = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        # No spec file found – return empty dictionary.
        return {}

    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                # Assume YAML; try to import yaml.
                try:
                    import yaml
                except ImportError:
                    # Fallback: treat as plain text key=value lines.
                    data = {}
                    for line in f:
                        if "=" in line:
                            k, v = (part.strip() for part in line.split("=", 1))
                            data[k] = v
                else:
                    data = yaml.safe_load(f)
    except Exception:
        # Any error while reading/parsing – return empty dict.
        return {}

    flat = {}
    _flatten(data, "", flat)
    return flat

def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        env_var_name = getattr(self, 'CONFIG_ENV', 'CONFIG_PATH')
        # Retrieve the config path attribute if it exists
        config_path = getattr(self, 'config_path', None)
        if config_path is None:
            return
        try:
            # Only set the variable if it is not already defined
            if env_var_name not in os.environ:
                os.environ[env_var_name] = str(config_path)
        except Exception:
            # Silently ignore errors such as invalid path conversion or os.env write issues
            pass
